        segments.pop()
        let currentPath = ''
        for (const segment of segments) {
            currentPath = currentPath.length === 0 ? segment : `${currentPath}/${segment}`
            folderPaths.add(currentPath)
        }
    }

    return [...folderPaths].sort((left, right) => left.localeCompare(right))
}

